package challenge.leetcode.hard.lexicographicallySmallestGeneratedString;

import java.util.HashMap;
import java.util.Map;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/**
 * @author Administrator
 * @Created 07:02 Tue 31 March 2026
 * @Project 3C: Competitive Coding Challenges
 **/
@DisplayName("3474. Lexicographically Smallest Generated String")
class LexicographicallySmallestGeneratedStringTest
{
	private static final Map<Input, String> MAP = new HashMap<>();

	static
	{
		MAP.put(new Input("F","d"),"");
		MAP.put(new Input("TFTF","ab"),"");
		MAP.put(new Input("TFTF","abc"),"");
		MAP.put(new Input("TTFFT","fff"),"");
		MAP.put(new Input("","bab"),"");
	}

	@Test
	void generateString()
	{
		for (Map.Entry<Input, String> entry : MAP.entrySet())
		{
			final String a = entry.getKey().a();
			final String b = entry.getKey().b();
			final String expected = entry.getValue();
			final String actual = LexicographicallySmallestGeneratedString.generateString(a, b);

			String message = String.format("Test failed for case:"
					+ "%n%10s :"
					+ "%n%10s : %s"
					+ "%n%10s : %s"
					+ "%n%10s :"
					+ "%n%10s : %s"
					+ "%n%10s : %s"
					+ "%n%10s ",
				"Input",
				"A", a,
				"B", a,
				"Output",
				"Expected", expected,
				"Actual", actual,
				""
			);

			assertEquals(actual, expected, message);
		}
	}
}
record Input(String a, String b)
{

}